"  }catch(e){}",
"}",
"function rDenStats(){",
"  var box=$('#otp-denStats');if(!box)return;",
"  var o=statsGet(),ids=Object.keys(o).filter(function(k){return o[k].o||o[k].f}),h='<div class=\"dx-stats\"><h3>Your marketplaces</h3>',mf=1,mo=1,top;",
