"function rDenMine(){",
"  var box=$('#otp-denMine');if(!box)return;",
"  var now=Date.now(),D=86400000,runs=runsGet(),finds=findsGet(),rv=[],rl=[],fv=[],fl=[],i,j,k,n,tr=0,tf=0;",
