"    for(j=0;j<runs.length;j++)if(runs[j].at&&dxDay(runs[j].at)===k)n++;",
"    rv.push(n);rl.push(dxShort(now-i*D)+': '+n+(n===1?' search':' searches'));tr+=n;",
"  }",
