"var NR_DAYS=['Sunday','Monday','Tuesday','Wednesday','Thursday','Friday','Saturday'],NR_D3=['Sun','Mon','Tue','Wed','Thu','Fri','Sat'],NR_MON=['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec'];",
