"function nrWeekday(day){var m=/^(\\d{4})-(\\d{2})-(\\d{2})$/.exec(day||'');return m?new Date(Date.UTC(+m[1],+m[2]-1,+m[3],12)).getUTCDay():new Date().getDay()}",
