"function rNrDays(){var el=$('#otp-nrDays');if(!el)return;var D=nrDays();if(!NR.day||NR.day<D[0].day)NR.day=D[0].day;el.innerHTML=D.map(function(x){return '<button type=\"button\" class=\"hubc'+(x.day===NR.day?' on':'')+'\" data-nrday=\"'+x.day+'\" aria-pressed=\"'+(x.day===NR.day)+'\">'+x.label+'</button>'}).join('')}",
